package com.securebiz.copilot.repository;import com.securebiz.copilot.api.CopilotDtos.EvidenceRef;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class CopilotRepository{private final JdbcClient jdbc;public CopilotRepository(JdbcClient jdbc){this.jdbc=jdbc;}public Optional<AlertEvidence>alert(UUID id){return jdbc.sql("""
 SELECT a.id,a.user_id,a.status,a.severity,a.risk_score,a.reasons,ra.contributions,ap.anomaly_score,ap.model_version,fs.window_start,fs.window_end
 FROM security_alerts a JOIN risk_assessments ra ON ra.id=a.risk_assessment_id JOIN anomaly_predictions ap ON ap.id=ra.prediction_id JOIN feature_snapshots fs ON fs.id=ap.feature_snapshot_id WHERE a.id=:id
 """).param("id",id).query((r,n)->new AlertEvidence(r.getObject("id",UUID.class),r.getObject("user_id",UUID.class),r.getString("status"),r.getString("severity"),r.getDouble("risk_score"),r.getString("reasons"),r.getString("contributions"),r.getDouble("anomaly_score"),r.getString("model_version"),r.getTimestamp("window_start").toInstant(),r.getTimestamp("window_end").toInstant())).optional();}public List<EvidenceRef>timeline(AlertEvidence a){var rows=jdbc.sql("SELECT id,occurred_at,action,module,result FROM activity_logs WHERE user_id=:user AND occurred_at>=:from AND occurred_at<:to ORDER BY occurred_at LIMIT 100").param("user",a.userId()).param("from",java.sql.Timestamp.from(a.windowStart())).param("to",java.sql.Timestamp.from(a.windowEnd())).query((r,n)->new EvidenceRef("E"+n,r.getObject("id",UUID.class).toString(),r.getTimestamp("occurred_at").toInstant().toString(),r.getString("action"),r.getString("module"),r.getString("result"))).list();return rows;}public void save(UUID id,UUID alert,UUID actor,String question,String answer,String provider,String model,String promptVersion,String evidence,double latency){jdbc.sql("INSERT INTO copilot_interactions(id,alert_id,asked_by,question,answer,provider,model,prompt_version,evidence_refs,latency_ms) VALUES(:id,:alert,:actor,:question,:answer,:provider,:model,:prompt,CAST(:evidence AS jsonb),:latency)").param("id",id).param("alert",alert).param("actor",actor).param("question",question).param("answer",answer).param("provider",provider).param("model",model).param("prompt",promptVersion).param("evidence",evidence).param("latency",latency).update();}public record AlertEvidence(UUID id,UUID userId,String status,String severity,double riskScore,String reasons,String contributions,double anomalyScore,String modelVersion,java.time.Instant windowStart,java.time.Instant windowEnd){}}
